      "description": "Estimation History adds to Session Log Data."
    },
    {
      "from": "Agreed Estimate",
      "to": "Session Log Data",
      "description": "Agreed Estimate stored in Session Log Data."
    },
    {
      "from": "Stakeholder",
      "to": "Session Log Data",
      "description": "Stakeholder reviews Session Log Data."
    }
  ]
}
```
